/**
 * Extensions registry (Milestone 4) — bundled (converted) extensions.
 *
 * A bundled extension is a TypeScript module generated by the converter
 * and checked into the repo (examples/). The registry maps its slug to
 * the module's `activate(wp)` so the conversion job (or an admin action)
 * can enable it. Converted code runs only through the Wordless extension
 * API — it cannot load code dynamically or run shell commands.
 *
 * The marketplace (listing, installing and activating arbitrary
 * extensions from uploads) is Phase 8; this registry covers the
 * converter's own output only.
 */
import type { WordPressApi } from "../../compat/wordpress";
import * as helloDolly from "../../../examples/hello-dolly/index";

export interface BundledExtension {
  slug: string;
  name: string;
  version: string;
  description: string;
  activate: (wp: WordPressApi) => void;
}

export const BUNDLED_EXTENSIONS: Record<string, BundledExtension> = {
  "hello-dolly": {
    slug: "hello-dolly",
    name: helloDolly.extensionMeta.name,
    version: helloDolly.extensionMeta.version,
    description: helloDolly.extensionMeta.description ?? "Converted from the bundled Hello Dolly plugin (WordPress 7.1.5).",
    activate: helloDolly.activate,
  },
};

export function bundledExtension(slug: string): BundledExtension | undefined {
  return BUNDLED_EXTENSIONS[slug];
}
